import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
const pg=await b.newPage({viewport:{width:390,height:844}})
await pg.goto('http://127.0.0.1:8099/#/pages/inspection/index?kind=pre',{waitUntil:'domcontentloaded',timeout:25000}).catch(e=>console.log('goto',e.message))
await pg.waitForTimeout(2500)
const info = await pg.evaluate(()=>{
  const icon=document.querySelector('.ref-date-icon')
  const text=document.querySelector('.ref-date-text')
  const picker=document.querySelector('uni-picker')
  const out={iconExists:!!icon, iconSrc:icon?icon.getAttribute('src'):null, iconRect:icon?{w:icon.getBoundingClientRect().width,h:icon.getBoundingClientRect().height}:null, dateText:text?text.textContent.trim():null, pickerExists:!!picker, pickerW:picker?picker.getBoundingClientRect().width:null}
  return out
})
console.log('INFO:', JSON.stringify(info,null,2))
await pg.screenshot({path:'D:/repository/_dp_before.png'})
// click the date field to open picker
try{
  await pg.click('.ref-date-input')
  await pg.waitForTimeout(1200)
  const popup = await pg.evaluate(()=>{
    // uni h5 date picker popup container
    const sel=['uni-picker .uni-picker-container','.uni-picker-container','uni-picker .uni-picker','.uni-picker-content']
    for(const s of sel){const el=document.querySelector(s); if(el){return {sel:s, visible:el.getBoundingClientRect().height>0, text:(el.textContent||'').trim().slice(0,60)}}}
    return {none:true, pickerElems: document.querySelectorAll('uni-picker *').length}
  })
  console.log('POPUP after click:', JSON.stringify(popup,null,2))
}catch(e){console.log('click err',e.message)}
await pg.screenshot({path:'D:/repository/_dp_after.png'})
await b.close()

