import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
const pg=await b.newPage({viewport:{width:390,height:844}})
await pg.goto('http://127.0.0.1:8095/#/pages/inspection/index?kind=pre',{waitUntil:'domcontentloaded',timeout:25000}).catch(()=>{})
await pg.waitForTimeout(2500)
const before = await pg.evaluate(()=>({icon:!!document.querySelector('.ref-date-icon'), text:(document.querySelector('.ref-date-text')||{}).textContent, picker:!!document.querySelector('uni-picker')}))
await pg.click('.ref-date-input').catch(()=>{})
await pg.waitForTimeout(1000)
const popup = await pg.evaluate(()=>{const el=document.querySelector('.uni-picker-container'); return {visible: el? el.getBoundingClientRect().height>0:false, hasCancelDone: el? /取消/.test(el.textContent) && /完成/.test(el.textContent):false}})
console.log('before:', JSON.stringify(before), '| popup:', JSON.stringify(popup))
await b.close()
